CREATE VIEW `design_fom_nodes` AS SELECT `f`.*, `n`.`type`, `n`.`within`, `n`.`depth`, `n`.`x`, `n`.`y`, `n`.`w`, `n`.`h`, `n`.`fill_kind`, `n`.`fill`, `n`.`fill_opacity`, `n`.`stroke`, `n`.`stroke_weight`, `n`.`radius`, `n`.`font_family`, `n`.`font_weight`, `n`.`font_size`, `n`.`line_height`, `n`.`text_align`, `n`.`text`, `n`.`opacity`, `n`.`image`, `n`.`asset`, `n`.`token_fill`, `n`.`token_stroke`, `n`.`token_radius`, `n`.`token_font`, `n`.`token_gap`, `n`.`token_padding` FROM `design_fom` `f` LEFT JOIN `design_nodes` `n` ON `n`.`target_id` = `f`.`target_id` AND `n`.`node` = `f`.`node`;
